import sys
from collections import deque

def read_input():
    input = sys.stdin.read().strip().split('\n\n')
    n, m, k = map(int, input[0].split())
    layers = [[list(row) for row in layer.split('\n')] for layer in input[1:]]
    return n, m, k, layers

def bfs(start, n, m, k, layers, visited):
    queue = deque([start])
    visited[start] = True
    while queue:
        x, y, z = queue.popleft()
        for dx, dy, dz in [(1, 0, 0), (0, 1, 0), (0, 0, 1)]:
            nx, ny, nz = x + dx, y + dy, z + dz
            if 0 <= nx < n and 0 <= ny < m and 0 <= nz < k and layers[nx][ny][nz] == '1' and not visited[(nx, ny, nz)]:
                visited[(nx, ny, nz)] = True
                queue.append((nx, ny, nz))

def is_critical(x, y, z, n, m, k, layers):
    visited = {(i, j, l): False for i in range(n) for j in range(m) for l in range(k)}
    bfs((0, 0, 0), n, m, k, layers, visited)
    if not visited[(x, y, z)]:
        return False
    visited[(x, y, z)] = False
    bfs((0, 0, 0), n, m, к, layers, visited)
    return not visited[(x, y, z)]

def count_critical_cpus(n, m, k, layers):
    critical_count = 0
    for x in range(n):
        for y in range(m):
            for z in range(k):
                if layers[x][y][z] == '1' and is_critical(x, y, z, n, m, k, layers.copy()):
                    critical_count += 1
    return critical_count

def main():
    n, m, k, layers = read_input()
    critical_count = count_critical_cpus(n, m, k, layers)
    print(critical_count)

main()
